// Test stack: Axiom datasets + ingest token, a sourcemaps R2 bucket, a bucket-scoped upload token, the relay worker on workers.dev.
import alchemy from 'alchemy';
import { AccountApiToken, R2Bucket, Worker } from 'alchemy/cloudflare';
import { Dataset, IngestToken } from 'alchemy/axiom';

const app = await alchemy('relay-observe', { stage: process.env.STAGE ?? 'observe-test' });
const logs = await Dataset('relay-logs');
const ingest = await IngestToken('relay-ingest', { datasets: [logs] });
const sourcemaps = await R2Bucket('sourcemaps');
const upload = await AccountApiToken('sourcemap-upload', { policies: [{ effect: 'allow', permissionGroups: ['Workers R2 Storage Write'], resources: { [`com.cloudflare.edge.r2.bucket.${sourcemaps.accountId}_default_${sourcemaps.name}`]: '*' } }] });
export const worker = await Worker('relay', { entrypoint: '../../src/worker.ts', url: true, bindings: { AXIOM_TOKEN: ingest.token, AXIOM_DATASET: logs.name, SOURCEMAPS: sourcemaps } });
console.log({ url: worker.url, uploadTokenId: upload.id });
await app.finalize();

