import 'dotenv/config';
import Anthropic from '@anthropic-ai/sdk';
import { readFileSync, mkdirSync, writeFileSync } from 'node:fs';
import { parseArgs } from 'node:util';
import { runVoicePipeline } from '../../src/voice/pipeline.ts';

const { values } = parseArgs({ options: { out: { type: 'string' } } });
if (!values.out) throw new Error('--out is required');
if (!process.env.ANTHROPIC_API_KEY) { console.error('ANTHROPIC_API_KEY is not set'); process.exit(1); }
const judge = new Anthropic();
const cases = readFileSync('evals/voice/cases.ndjson', 'utf8').trim().split('\n').map((line) => JSON.parse(line));
mkdirSync(values.out, { recursive: true });
const rows = [];
for (const c of cases) {
  const reply = await runVoicePipeline(c.input);
  const verdict = await judge.messages.create({ model: 'claude-haiku-5-5', max_tokens: 200, messages: [{ role: 'user', content: `Rubric: ${c.rubric}\nReply: ${reply}\nPass or fail?` }] });
  rows.push({ id: c.id, reply, verdict: verdict.content });
}
writeFileSync(`${values.out}/results.json`, JSON.stringify(rows, null, 2));

