import OpenAI from 'openai';
const client = new OpenAI({ baseURL: 'https://openrouter.ai/api/v1', apiKey: process.env.OPENROUTER_API_KEY });
export async function runVoicePipeline(input: string) {
  const res = await client.chat.completions.create({ model: 'openai/gpt-6-mini', messages: [{ role: 'user', content: input }] });
  return res.choices[0]?.message.content ?? '';
}

