import type { RequestHandler } from 'express';
import { verifySession } from '../lib/workos';

// The WorkOS session cookie sets req.user; a request without it has none.
export const session: RequestHandler = async (req, _res, next) => {
  req.user = (await verifySession(req.cookies.wos_session)) ?? undefined;
  next();
};

