// Syncs config/store.json to App Store Connect with the asc CLI session.
// node scripts/store-config.mjs plan   prints the diff against App Store Connect
// node scripts/store-config.mjs apply  writes it
import { execFileSync } from 'node:child_process';
import { readFileSync } from 'node:fs';

const mode = process.argv[2];
if (mode !== 'plan' && mode !== 'apply') throw new Error('usage: store-config.mjs plan|apply');
const want = JSON.parse(readFileSync('config/store.json', 'utf8'));
const asc = (...args) => JSON.parse(execFileSync('asc', [...args, '--json'], { encoding: 'utf8' }));
const group = asc('subscriptions', 'groups').find((g) => g.referenceName === want.subscriptionGroup);
const have = new Set(group.products.map((p) => p.productId));
const testers = new Set(asc('sandbox', 'list').map((t) => t.email));
const changes = [
  ...want.products.filter((id) => !have.has(id)).map((id) => ({ op: '+', what: `product ${id}`, args: ['subscriptions', 'create', '--group', group.id, '--product-id', id] })),
  ...want.sandboxTesters.filter((email) => !testers.has(email)).map((email) => ({ op: '+', what: `sandbox tester ${email}`, args: ['sandbox', 'create', '--email', email] })),
];
for (const c of changes) console.log(`${c.op} ${c.what}`);
if (mode === 'plan') { console.log(`Plan: ${changes.length} to add. Run apply to write.`); process.exit(0); }
for (const c of changes) execFileSync('asc', c.args, { stdio: 'inherit' });
